<?php require_once 'config.php'; if (current_user()) redirect(current_user()['role']==='admin'?'admin_dashboard.php':'menu.php');
if ($_SERVER['REQUEST_METHOD']==='POST') { $email=trim($_POST['email']??''); $pass=$_POST['password']??''; $s=db()->prepare("SELECT * FROM users WHERE email=? AND role='user'"); $s->bind_param('s',$email); $s->execute(); $u=$s->get_result()->fetch_assoc(); if ($u && password_verify($pass,$u['password_hash'])) { $_SESSION['user']=['id'=>$u['id'],'name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']]; redirect('menu.php'); } flash('Invalid user email or password.'); }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="auth-wrap"><section class="auth-art"><img src="assets/canteen.svg" alt="Canteen"><h1>Smart Canteen<br>Ordering System</h1><p>Order Smart, Eat Fresh</p></section><form class="auth-card" method="post"><h2>Login</h2><p>Welcome back! Please login to continue</p><?php if($m=flash()):?><div class="error"><?=h($m)?></div><?php endif;?><label>Email<input type="email" name="email" required placeholder="Enter your email"></label><label>Password<input type="password" name="password" required placeholder="Enter your password"></label><button>Login</button><p>Don't have an account? <a href="register.php">Register here</a></p><p><a href="admin_login.php">Admin login</a></p></form></div></body></html>
